class BiddingApprovalTest extends BiddingHttpFixture {
    @Test void approvalCommandIsARealApproverGatedCommand() throws Exception {
        var project=api("POST","/projects","owner",workspace,Map.of("operationId",UUID.randomUUID().toString(),"name","审批门禁","lotName","一标段"),200);
        ObjectNode payload=json.createObjectNode().put("artifactId","missing").put("digest","forged");
        payload.putObject("inspection").put("opened",true).put("layoutChecked",true).put("reason","checked");
        ObjectNode command=json.createObjectNode().put("operationId",UUID.randomUUID().toString());
        command.set("expected",json.valueToTree(ref(project)));command.put("action","APPROVE_ARTIFACT").set("payload",payload);
        JsonNode denied=api("POST","/projects/"+project.path("id").asText()+"/commands","member",workspace,command,403);
        assertEquals("FORBIDDEN",denied.path("data").path("code").asText());
        JsonNode missing=api("POST","/projects/"+project.path("id").asText()+"/commands","owner",workspace,command,404);
        assertTrue(missing.toString().contains("ARTIFACT_NOT_FOUND"));
    }
}

