    private long seedSkill(String name,java.util.Map<String,java.nio.file.Path> dirs)throws Exception {long id=IDS.incrementAndGet();java.nio.file.Path source=java.nio.file.Path.of(getClass().getResource("/skills/"+name+"/SKILL.md").toURI()).getParent(),dest=java.nio.file.Files.createDirectory(temp.resolve("skill-"+id));try(var walk=java.nio.file.Files.walk(source)){for(var path:walk.toList())if(java.nio.file.Files.isRegularFile(path)){var target=dest.resolve(source.relativize(path).toString());java.nio.file.Files.createDirectories(target.getParent());java.nio.file.Files.copy(path,target);}}jdbc.update("INSERT INTO mate_skill(id,name,skill_type,version,skill_content,config_json,enabled,builtin,workspace_id,create_time,update_time,deleted) VALUES(?,?,'custom','1.0.0',?,?,TRUE,FALSE,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,0)",id,name,java.nio.file.Files.readString(dest.resolve("SKILL.md")),json.writeValueAsString(java.util.Map.of("skillDir",dest.toString())),Long.valueOf(workspace));dirs.put(name,dest);return id;}
