    private ObjectNode dispatchAndGenerate(BiddingTypes.Scope scope,BiddingTypes.Ref projectRef,BiddingTypes.Ref manuscript,BiddingTypes.Ref template,BiddingTypes.Ref format,String mode,String label)throws Exception {ObjectNode dispatch=json.createObjectNode().set("manuscriptRef",json.valueToTree(manuscript));dispatch.set("templateRef",json.valueToTree(template));dispatch.set("formatRef",json.valueToTree(format));dispatch.put("mode",mode);artifacts.dispatch(scope,new BiddingTypes.Command(label,projectRef,"DISPATCH_EXPORT",dispatch));BiddingTypes.Claim claim=tasks.claimDue(java.time.Instant.now(),label,1).getFirst();var options=new vip.mate.agent.execution.ProjectExecutionOptions(claim.attemptId(),claim.modelConfigId(),claim.configDigest(),"bidding-document-export",claim.skill().digest(),claim.skill().files(),java.util.Set.of("bidding_export_document"),new BiddingToolScope(claim),0,false,false,12);var context=new org.springframework.ai.chat.model.ToolContext(java.util.Map.of(vip.mate.agent.execution.ProjectExecutionOptions.TOOL_CONTEXT_KEY,options));ObjectNode manifest=(ObjectNode)json.readTree(exportTool.generate(json.writeValueAsString(manuscript),json.writeValueAsString(template),json.writeValueAsString(format),context));tasks.complete(claim,new BiddingTypes.Execution(manifest,null,claim.skill().digest(),claim.configDigest(),null));return manifest;}
