    private BiddingTypes.Ref classifyTodo(BiddingTypes.Scope scope,BiddingTypes.Ref todo,BiddingTypes.Ref source,String blockId,boolean affectsTechnical)throws Exception {ObjectNode command=json.createObjectNode().put("operationId","classify-"+todo.version()+"-"+affectsTechnical+"-"+UUID.randomUUID());command.set("expected",json.valueToTree(todo));command.put("action","CLASSIFY_HUMAN_TODO");ObjectNode payload=json.createObjectNode().set("todoRef",json.valueToTree(todo));payload.put("affectsTechnical",affectsTechnical).put("reason",affectsTechnical?"事实影响技术响应":"经核实仅属商务事项");payload.putArray("evidenceRefs").addObject().put("sourceId",source.id()).put("version",source.version()).put("blockId",blockId).put("quote","接口响应时间不超过2秒");command.set("payload",payload);var response=http("POST","/api/v1/bidding/projects/"+scope.projectId()+"/commands",command,200);return json.treeToValue(response.path("data").path("ref"),BiddingTypes.Ref.class);}
    private void completeReviewTasks(BiddingTypes.Scope scope,BiddingTypes.Ref manuscript,int count,BiddingTypes.Ref source,String blockId,String severity)throws Exception {for(int i=0;i<count;i++){var claim=tasks.claimDue(java.time.Instant.now(),"approval-review-"+i,1).getFirst();ObjectNode output=json.createObjectNode().put("schemaVersion","1");var findings=output.putArray("findings");if(i==0){ObjectNode finding=findings.addObject().put("id","GAP-1").put("severity",severity).put("category","TECHNICAL_GAP").put("description","关键性能响应需要人工核实").put("recommendation","核对招标文件和响应证据");finding.putArray("chapterRefs").add(claim.input().path("chapters").get(0).path("chapterRef").deepCopy());finding.putArray("requirementRefs").add("REQ-1");finding.putArray("evidenceRefs").addObject().put("sourceId",source.id()).put("version",source.version()).put("blockId",blockId).put("quote","接口响应时间不超过2秒");}ObjectNode coverage=output.putObject("coverage");var chapters=coverage.putArray("chapterRefs");var requirements=coverage.putArray("requirementRefs");for(var chapter:claim.input().path("chapters"))chapters.add(chapter.path("chapterRef").deepCopy());for(var req:claim.input().path("requirements"))requirements.add(req.path("id").asText());coverage.put("crossChapterReviewed",claim.input().path("_biddingTargetId").asText().endsWith(":cross"));output.putArray("limitations");output.putArray("warnings");tasks.complete(claim,new BiddingTypes.Execution(output,null,claim.skill().digest(),claim.configDigest(),null));}}
    private BiddingTypes.Ref save(BiddingTypes.Scope scope,BiddingTypes.Ref ref,ObjectNode body,java.util.List<BiddingTypes.Ref> refs,String status,boolean head)throws Exception {jdbc.update("INSERT INTO mate_bidding_revision(id,workspace_id,project_id,kind,object_id,version,payload_json,input_refs_json,status,digest,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP)",java.util.UUID.randomUUID().toString(),workspace,scope.projectId(),ref.kind(),ref.id(),ref.version(),json.writeValueAsString(body),json.writeValueAsString(refs),status,ref.digest());if(head)jdbc.update("MERGE INTO mate_bidding_head(workspace_id,project_id,kind,object_id,version,selected_ref_json) KEY(workspace_id,project_id,kind,object_id) VALUES(?,?,?,?,?,?)",workspace,scope.projectId(),ref.kind(),ref.id(),ref.version(),json.writeValueAsString(ref));return ref;}
    private String digest(Object value)throws Exception{return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(json.writeValueAsBytes(value)));}
    private byte[] docx(String text)throws Exception{try(var doc=new org.apache.poi.xwpf.usermodel.XWPFDocument();var out=new java.io.ByteArrayOutputStream()){doc.createParagraph().createRun().setText(text);doc.write(out);return out.toByteArray();}}
